-- Tables + metatables: an object delegates missing keys to its prototype.
local Shape = {}
Shape.__index = Shape

function Shape:extend(name, area)
  local proto = setmetatable({ name = name, area = area }, self)
  proto.__index = proto
  return proto
end

function Shape:new(fields)
  return setmetatable(fields, self)
end

function Shape:describe()
  return ("%s: %d"):format(self.name, self:area())
end

local Rectangle = Shape:extend("Rectangle", function(s) return s.width * s.height end)
local Triangle  = Shape:extend("Triangle",  function(s) return s.base * s.height / 2 end)

for _, shape in ipairs({ Rectangle:new{ width = 3, height = 4 },
                         Triangle:new{ base = 10, height = 3 } }) do
  print(shape:describe())
end
